SELECT CASE WHEN amount >= 1640 THEN 'high' WHEN amount >= 520 THEN 'mid' ELSE 'low' END AS amount_bucket, QUARTER(paid_at) AS paid_quarter, AVG(amount) AS avg_amount, SUM(CASE WHEN method = 'bank_transfer' THEN 1 ELSE 0 END) AS bank_transfer_count FROM payments GROUP BY CASE WHEN amount >= 1640 THEN 'high' WHEN amount >= 520 THEN 'mid' ELSE 'low' END, QUARTER(paid_at) ORDER BY paid_quarter DESC, amount_bucket;
